import { generateAILeaderboard } from './generator';
import type { LeaderboardEntry, LeaderboardGenerationOptions, LeaderboardStats } from './types';

export const PLAYER_RATING_STORAGE_KEY = 'crazy-putt-arena.rating';
export const DEFAULT_PLAYER_RATING = 1000;
const MIN_RATING = 100;
const MAX_RATING = 3500;

export interface RatingStorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

function clampRating(rating: number): number {
  return Math.round(Math.min(MAX_RATING, Math.max(MIN_RATING, rating)));
}

/** Browsers without storage (private mode, SSR, tests) simply fall back to the default rating. */
function browserStorage(): RatingStorageLike | null {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
}

export function loadPlayerRating(
  storage: RatingStorageLike | null = browserStorage(),
  fallback = DEFAULT_PLAYER_RATING,
): number {
  if (!storage) return fallback;
  try {
    const raw = storage.getItem(PLAYER_RATING_STORAGE_KEY);
    if (raw === null) return fallback;
    const value = Number.parseFloat(raw);
    return Number.isFinite(value) ? clampRating(value) : fallback;
  } catch {
    return fallback;
  }
}

export function savePlayerRating(rating: number, storage: RatingStorageLike | null = browserStorage()): boolean {
  if (!storage || !Number.isFinite(rating)) return false;
  try {
    storage.setItem(PLAYER_RATING_STORAGE_KEY, String(clampRating(rating)));
    return true;
  } catch {
    return false;
  }
}

export interface LocalPlayerStanding {
  id: string;
  displayName: string;
  rating: number;
  ballStyleId?: string;
  countryCode?: string;
  stats?: Partial<LeaderboardStats>;
}

export interface LeaderboardStandingsOptions extends LeaderboardGenerationOptions {
  player?: LocalPlayerStanding;
}

function playerStats(stats: Partial<LeaderboardStats> = {}): LeaderboardStats {
  const matchesPlayed = Math.max(0, Math.round(stats.matchesPlayed ?? 0));
  const wins = Math.min(matchesPlayed, Math.max(0, Math.round(stats.wins ?? 0)));
  const podiums = Math.min(matchesPlayed, Math.max(wins, Math.round(stats.podiums ?? wins)));
  const holesPlayed = Math.max(0, Math.round(stats.holesPlayed ?? 0));
  const holesInOne = Math.min(holesPlayed, Math.max(0, Math.round(stats.holesInOne ?? 0)));
  const winRate = stats.winRate ?? (matchesPlayed > 0 ? Math.round((wins / matchesPlayed) * 1000) / 1000 : 0);
  return {
    matchesPlayed,
    wins,
    podiums,
    holesPlayed,
    holesInOne,
    averageStrokes: Math.max(0, stats.averageStrokes ?? 0),
    winRate: Math.min(1, Math.max(0, winRate)),
  };
}

/** Same ordering the generator uses, so the human slots into the AI field consistently. */
function byStanding(a: LeaderboardEntry, b: LeaderboardEntry): number {
  return b.rating - a.rating || b.stats.wins - a.stats.wins || a.displayName.localeCompare(b.displayName);
}

/** Generated AI field with the local player merged in at the position of their rating. */
export function buildLeaderboardStandings(options: LeaderboardStandingsOptions = {}): LeaderboardEntry[] {
  const { player, ...generation } = options;
  const generated = generateAILeaderboard(generation);
  if (!player) return generated;

  const entry: LeaderboardEntry = {
    id: player.id,
    displayName: player.displayName,
    kind: 'human',
    ballStyleId: player.ballStyleId ?? 'classic',
    rating: clampRating(player.rating),
    rank: 0,
    countryCode: player.countryCode ?? 'YOU',
    stats: playerStats(player.stats),
  };

  return [...generated.filter((other) => other.id !== entry.id), entry]
    .sort(byStanding)
    .map((other, index) => ({ ...other, rank: index + 1 }));
}
